def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    import re

    functions = {"SUM", "MIN", "MAX", "IF"}
    precedence = {
        "=": 1, "<>": 1, "<": 1, "<=": 1, ">": 1, ">=": 1,
        "+": 2, "-": 2, "*": 3, "/": 3, "neg": 4,
    }
    tokenizer = re.compile(r"[A-Z]+[0-9]*|[0-9]+|<>|<=|>=|[+\-*/():,=<>]")
    nodes = []

    def number(text):
        text = text.strip()
        sign = 1
        if text[0] in "+-":
            if text[0] == "-":
                sign = -1
            text = text[1:]
        result = 0
        for i in range(0, len(text), 9):
            chunk = text[i:i + 9]
            result = result * (10 ** len(chunk)) + int(chunk)
        return sign * result

    def add(node):
        nodes.append(node)
        return len(nodes) - 1

    def parse(content):
        if not content.startswith("="):
            return add(("number", number(content)))

        tokens = tokenizer.findall(content[1:])
        operands = []
        operators = []
        argument_counts = []
        expect_operand = True

        def reduce_operator():
            op = operators.pop()
            right = operands.pop()
            if op == "neg":
                operands.append(add(("neg", right)))
            else:
                left = operands.pop()
                operands.append(add((op, left, right)))

        i = 0
        while i < len(tokens):
            token = tokens[i]

            if token[0].isdigit():
                operands.append(add(("number", number(token))))
                expect_operand = False

            elif token in functions:
                operators.append(token)
                expect_operand = True

            elif token[0].isalpha():
                if i + 1 < len(tokens) and tokens[i + 1] == ":":
                    operands.append(add(("range", token, tokens[i + 2])))
                    i += 2
                else:
                    operands.append(add(("reference", token)))
                expect_operand = False

            elif token == "(":
                is_call = bool(operators and operators[-1] in functions)
                operators.append("(")
                argument_counts.append(1 if is_call else 0)
                expect_operand = True

            elif token == ",":
                while operators[-1] != "(":
                    reduce_operator()
                argument_counts[-1] += 1
                expect_operand = True

            elif token == ")":
                while operators[-1] != "(":
                    reduce_operator()
                operators.pop()
                count = argument_counts.pop()
                if count:
                    function = operators.pop()
                    arguments = tuple(operands[-count:])
                    del operands[-count:]
                    operands.append(add((function, arguments)))
                expect_operand = False

            elif token == "-" and expect_operand:
                operators.append("neg")

            else:
                while (
                    operators
                    and operators[-1] != "("
                    and precedence[operators[-1]] >= precedence[token]
                ):
                    reduce_operator()
                operators.append(token)
                expect_operand = True

            i += 1

        while operators:
            reduce_operator()
        return operands[0]

    roots = {name: parse(content) for name, content in cells.items()}
    results = {}
    active = set()

    def argument_tasks(arguments):
        for index in arguments:
            node = nodes[index]
            if node[0] != "range":
                yield ("evaluate", index)
                continue

            first, last = node[1], node[2]
            c1, c2 = sorted((ord(first[0]), ord(last[0])))
            r1, r2 = sorted((int(first[1:]), int(last[1:])))
            for row in range(r1, r2 + 1):
                for column in range(c1, c2 + 1):
                    name = chr(column) + str(row)
                    if name in cells:
                        yield ("cell", name)

    for start in cells:
        if start in results:
            continue

        stack = [("cell", start)]
        value = 0

        while stack:
            task = stack.pop()
            kind = task[0]

            if kind == "cell":
                name = task[1]
                if name in results:
                    value = results[name]
                elif name not in roots:
                    value = 0
                elif name in active:
                    value = "#CYCLE!"
                else:
                    active.add(name)
                    stack.append(("finish", name))
                    stack.append(("evaluate", roots[name]))

            elif kind == "finish":
                name = task[1]
                results[name] = value
                active.remove(name)

            elif kind == "evaluate":
                node = nodes[task[1]]
                op = node[0]

                if op == "number":
                    value = node[1]
                elif op == "reference":
                    stack.append(("cell", node[1]))
                elif op == "neg":
                    stack.append(("negate",))
                    stack.append(("evaluate", node[1]))
                elif op == "IF":
                    condition, then_branch, else_branch = node[1]
                    stack.append(("choose", then_branch, else_branch))
                    stack.append(("evaluate", condition))
                elif op in functions:
                    stack.append(("aggregate", op, argument_tasks(node[1]), None))
                else:
                    stack.append(("left", op, node[2]))
                    stack.append(("evaluate", node[1]))

            elif kind == "negate":
                if isinstance(value, int):
                    value = -value

            elif kind == "left":
                if isinstance(value, int):
                    stack.append(("right", task[1], value))
                    stack.append(("evaluate", task[2]))

            elif kind == "right":
                if isinstance(value, str):
                    continue

                op, left, right = task[1], task[2], value
                if op == "+":
                    value = left + right
                elif op == "-":
                    value = left - right
                elif op == "*":
                    value = left * right
                elif op == "/":
                    if right == 0:
                        value = "#DIV/0!"
                    else:
                        quotient = abs(left) // abs(right)
                        value = -quotient if (left < 0) != (right < 0) else quotient
                elif op == "=":
                    value = int(left == right)
                elif op == "<>":
                    value = int(left != right)
                elif op == "<":
                    value = int(left < right)
                elif op == "<=":
                    value = int(left <= right)
                elif op == ">":
                    value = int(left > right)
                else:
                    value = int(left >= right)

            elif kind == "choose":
                if isinstance(value, int):
                    stack.append(("evaluate", task[1] if value else task[2]))

            elif kind == "aggregate":
                _, op, iterator, accumulated = task
                next_task = next(iterator, None)
                if next_task is None:
                    value = 0 if accumulated is None else accumulated
                else:
                    stack.append(("accumulate", op, iterator, accumulated))
                    stack.append(next_task)

            elif kind == "accumulate":
                if isinstance(value, str):
                    continue

                _, op, iterator, accumulated = task
                if accumulated is None:
                    accumulated = value
                elif op == "SUM":
                    accumulated += value
                elif op == "MIN":
                    accumulated = min(accumulated, value)
                else:
                    accumulated = max(accumulated, value)
                stack.append(("aggregate", op, iterator, accumulated))

    return {name: results[name] for name in cells}
